include!("../ffi.rs");
#[derive(Clone)]enum Op{Linear(u32,Vec<u32>),And(u32,i32,i32)}
struct Hybrid{variables:u32,primary:usize,false_var:u32,rows:Vec<(Vec<u32>,bool)>,clauses:Vec<Vec<i32>>,ops:Vec<Op>,memo:HashMap<N,u32>}
fn support(x:&N)->Vec<u32>{bits(x).into_iter().filter(|i|*i!=0).map(|i|i as u32).collect()}
impl Hybrid{
 fn fresh(&mut self)->u32{self.variables+=1;self.variables}
 fn literal(&mut self,f:&N)->i32{let vars=support(f);let v=if vars.is_empty(){self.false_var}else if vars.len()==1{vars[0]}else{let key=f>>1;if let Some(v)=self.memo.get(&key){*v}else{let v=self.fresh();self.ops.push(Op::Linear(v,vars.clone()));let mut row=vars;row.push(v);self.rows.push((row,false));self.memo.insert(key,v);v}};if f.bit(0){-(v as i32)}else{v as i32}}
 fn compile(a:&A,eq:&[u32],limit:usize)->Self{assert!(limit>0);let keep=active(a,eq);let mut h=Self{variables:a.inputs as u32+1,primary:a.inputs,false_var:a.inputs as u32+1,rows:vec![],clauses:vec![vec![-(a.inputs as i32+1)]],ops:vec![],memo:HashMap::new()};let mut fs=vec![N::zero();a.nodes.len()];fs[1]=N::one();for(i,node)in a.nodes.iter().enumerate().skip(2){if node[0]==1{fs[i]=N::one()<<(node[1]+1);continue;}if !keep[i]{continue;}if node[0]==2{let f=&fs[node[1]as usize]^&fs[node[2]as usize];if support(&f).len()>limit{let lit=h.literal(&f);fs[i]=N::one()<<lit.unsigned_abs();if lit<0{fs[i]^=N::one();}}else{fs[i]=f;}}else{let x=h.literal(&fs[node[1]as usize]);let y=h.literal(&fs[node[2]as usize]);let z=h.fresh();h.ops.push(Op::And(z,x,y));let z=z as i32;h.clauses.extend([vec![-x,-y,z],vec![x,-z],vec![y,-z]]);fs[i]=N::one()<<z;}}for wire in eq{let f=&fs[*wire as usize];h.rows.push((support(f),f.bit(0)));}h}
 fn extension(&self,input:&[bool])->Vec<bool>{assert_eq!(input.len(),self.primary);let mut values=vec![None;self.variables as usize+1];for(i,b)in input.iter().enumerate(){values[i+1]=Some(*b);}values[self.false_var as usize]=Some(false);for op in &self.ops{match op{Op::Linear(v,row)=>values[*v as usize]=Some(row.iter().fold(false,|x,v|x^values[*v as usize].unwrap())),Op::And(v,x,y)=>{let lit=|x:i32|values[x.unsigned_abs()as usize].unwrap()^(x<0);values[*v as usize]=Some(lit(*x)&lit(*y));}}}values.into_iter().skip(1).map(Option::unwrap).collect()}
 fn accepts(&self,v:&[bool])->bool{assert_eq!(v.len(),self.variables as usize);self.clauses.iter().all(|c|c.iter().any(|x|v[x.unsigned_abs()as usize-1]^(*x<0)))&&self.rows.iter().all(|(r,p)|r.iter().fold(false,|x,y|x^v[*y as usize-1])==*p)}
 fn native(&self,path:&str)->(ffi::Native,bool){let mut s=ffi::Native::new(path,self.variables as usize,self.primary);let mut ok=true;for c in &self.clauses{ok&=s.clause(c);}for(r,p)in &self.rows{ok&=s.xor(r,*p);}s.flush();(s,ok)}
 fn profile(&self,path:&str)->Value{let cuts:usize=self.rows.iter().map(|(r,_)|r.len().saturating_sub(3)/2).sum();let coefficients:usize=self.rows.iter().map(|(r,_)|r.len()).sum();let mut out=json!({"external_variables":self.variables,"primary_variables":self.primary,"xor_rows":self.rows.len(),"xor_coefficients":coefficients,"max_row":self.rows.iter().map(|(r,_)|r.len()).max().unwrap_or(0),"cnf_clauses_before_native_xor_cuts":self.clauses.len(),"preclean_cut_variable_estimate":cuts,"preclean_internal_estimate":self.variables as usize+cuts,"native_constructed":false});if self.variables as usize+cuts<=150000{let(s,ok)=self.native(path);let stats=s.stats();assert_eq!(stats[7],self.variables as u64);out["native_constructed"]=json!(true);out["construction_unit_consistent"]=json!(ok);out["native_internal_variables_after_flush"]=json!(stats[9]);out["native_stats"]=json!(stats);}else{out["skip_reason"]=json!("preregistered150000 preclean-internal-estimate cap");}out}
}
fn limits()->Vec<usize>{vec![1,2,4,8,16,32,usize::MAX]}
fn hybrid_controls(path:&str)->Value{let independent=norm_controls();let mut checked=0;for(n,modulus,d)in[(2,7,1),(3,11,2)]{let m=Model::new(n,N::from(modulus as u32),N::zero(),N::one(),N::one(),N::zero());let(a,eq)=build(&m,d,8);for limit in limits(){let h=Hybrid::compile(&a,&eq,limit);for mask in 0..1usize<<a.inputs{let input=(0..a.inputs).map(|i|mask>>i&1!=0).collect::<Vec<_>>();let extension=h.extension(&input);assert_eq!(h.accepts(&extension),a.eval(&input,&eq));checked+=1;}if n==2{let expected=(0..1usize<<a.inputs).filter(|mask|a.eval(&(0..a.inputs).map(|i|mask>>i&1!=0).collect::<Vec<_>>(),&eq)).collect::<std::collections::BTreeSet<_>>();let(mut s,mut ok)=h.native(path);let mut got=std::collections::BTreeSet::new();let start=Instant::now();while ok{assert!(start.elapsed().as_secs()<10);let(v,model)=s.solve(2.);if v==0{break;}assert_eq!(v,1);let values=model[1..].iter().map(|x|*x==1).collect::<Vec<_>>();assert!(h.accepts(&values));let mask=(0..a.inputs).fold(0usize,|m,i|m|((values[i]as usize)<<i));assert!(got.insert(mask));let block=(1..=a.inputs).map(|i|if values[i-1]{-(i as i32)}else{i as i32}).collect::<Vec<_>>();ok=s.clause(&block);}assert_eq!(got,expected);}}}let mut probe=ffi::Native::new(path,265,8);assert!(probe.xor(&(1..=265).collect::<Vec<_>>(),false));probe.flush();let stats=probe.stats();assert_eq!(stats[9],396);json!({"status":"passed","literal_norm_controls":independent,"hybrid_complete_primary_assignments":checked,"native_complete_model_set_arms":7,"native_models_per_arm":28,"cut_calibration_declared":265,"cut_calibration_internal":stats[9]})}
fn run_hybrid(id:&str,fixture:&str,path:&str)->Value{let start=Instant::now();let input:Value=serde_json::from_slice(&std::fs::read(fixture).unwrap()).unwrap();let z=hx(input["target"]["x_hex"].as_str().unwrap());let yt=hx(input["target"]["y_hex"].as_str().unwrap())^&z;assert_eq!(input["extension_field"]["degree"],83);for(i,b)in input["source_basis_hex"].as_array().unwrap().iter().enumerate(){assert_eq!(hx(b.as_str().unwrap()),N::one()<<i);}assert_eq!(input["source_basis_hex"].as_array().unwrap().len(),18);assert!(hx(input["source_offset_hex"].as_str().unwrap_or("0x0")).is_zero());let m=Model::new(83,hx(input["extension_field"]["modulus_hex"].as_str().unwrap()),hx(input["curve"]["a_hex"].as_str().unwrap()),hx(input["curve"]["b_hex"].as_str().unwrap()),z,yt);let(a,eq)=build(&m,18,8);assert_eq!(a.inputs,174);let mut arms=vec![];for limit in limits(){let h=Hybrid::compile(&a,&eq,limit);let mut p=h.profile(path);p["support_limit"]=if limit==usize::MAX{json!("dense")}else{json!(limit)};arms.push(p);if start.elapsed().as_secs()>=65{break;}}let complete=arms.len()==7;let baseline=arms[0]["native_internal_variables_after_flush"].as_u64().unwrap();let success=arms.iter().skip(1).take(5).filter_map(|x|x["native_internal_variables_after_flush"].as_u64()).any(|x|10*x<=9*baseline);json!({"schema":"scientific_result_v1","experiment_id":id,"status":if complete{"passed"}else{"inconclusive"},"summary":"Cut-aware exact norm representations were profiled using actual post-flush native coordinate counts; no root search or speed comparison.","evidence":{"arms":arms,"profile_complete":complete,"prediction_at_least10percent_internal_reduction":success,"native_solve_called":false,"native_gaussian_admission_measured":false,"original_root_count_exact":null,"release_gate_claim":false,"novelty_claim":false},"next_actions":["If hybrid counts improve, preregister a distinct hard search only after native initialization cost/matrix admission and literal full-model replay checks.","If native expansion refutes the count prediction, change parity sharing or source representation instead of rerunning the old hard timeout.","Keep original S3 ghost/exception/auxiliary closure and the matched8x full all-roots gate open."]})}
fn main(){let args=std::env::args().collect::<Vec<_>>();if args.get(1).is_some_and(|x|x=="controls"){println!("{}",hybrid_controls(args.get(2).expect("library")));return;}let t=Instant::now();let mut r=run_hybrid(args.get(1).expect("id"),args.get(2).expect("fixture"),args.get(3).expect("library"));let mut out=r.to_string();if t.elapsed().as_secs()>=75{r["status"]=json!("inconclusive");r["evidence"]["profile_complete"]=json!(false);out=r.to_string();}println!("{out}");}
